void handle_syscall_entry(void* ignore, struct pt_regs* regs, long id) {
    int syscall_number = regs->orig_ax;
    struct syscall_metadata *metadata = get_syscall_metadata(syscall_number);
    if (!metadata || !(metadata->flags & EVENT_ENABLED))
        return;

    int nr_args = metadata->nr_args;
    size_t size = sizeof(struct syscall_trace) + nr_args * sizeof(unsigned long);
    size = ALIGN(size, 8);

    struct syscall_trace *entry = (struct syscall_trace *)__get_tracedata();
    if (!entry)
        return;

    entry->id = syscall_number;
    for (int i = 0; i < nr_args; ++i) {
        entry->args[i] = regs->ax; // Assuming register mapping is known and handled
    }

    trace_submit(entry, size, metadata->event_type);
}

void syscall_enter_handler(void *ignore, struct pt_regs *regs, long id)
{
    int syscall_nr = (int)regs->ax;

    if (syscall_nr < 0 || syscall_nr >= NR_syscalls)
        return;

    struct syscall_metadata *meta = &syscall_metadata[syscall_nr];
    if (!meta->enabled)
        return;

    if (!trace_event_enabled(meta->event))
        return;

    unsigned int size = sizeof(struct syscall_trace_enter) + meta->arg_info_size;
    size = ALIGN(size, __alignof__(struct syscall_trace_enter));

    struct syscall_trace_enter *entry = kmalloc(size, GFP_KERNEL | __GFP_NOWARN);
    if (!entry)
        return;

    entry->nr = syscall_nr;
    entry->clock = local_clock();
    entry->ip = regs->ip;
    entry->sp = regs->sp;

    if (meta->prepare_enter)
        meta->prepare_enter(entry, regs);

    trace_buffer_submit(meta->event, entry, size);
}
